    $code = (isset($set['code']) && trim((string)$set['code']) !== '') ? trim((string)$set['code']) : '';
    
  // ---- Max cashout inline row (sub-bonus) ----
  // Display rules:
  //   NULL/empty/non-numeric → placeholder (invisible, but reserves vertical space)
